class AssessmentSystem:

    def __init__(self):
        self.students = {}

    def add_student(self, name, grade, major):
        if name in self.students:
            raise ValueError('Student name already exists')
        if not name:
            raise ValueError('Student name cannot be empty')
        if grade < 0 or grade > 12:
            raise ValueError('Grade must be between 0 and 12')
        if not major:
            raise ValueError('Student major cannot be empty')
        self.students[name] = {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        if not isinstance(name, str):
            raise TypeError('Student name must be a string')
        if not isinstance(course, str):
            raise TypeError('Course name must be a string')
        if not isinstance(score, int):
            raise TypeError('Score must be an integer')
        if score < 0 or score > 100:
            raise ValueError('Score must be between 0 and 100')
        if name not in self.students:
            raise KeyError(f"Student with name '{name}' does not exist")
        if course not in self.students[name]['courses']:
            self.students[name]['courses'][course] = score
        else:
            self.students[name]['courses'][course] += score

    def get_gpa(self, name):
        if not isinstance(name, str):
            raise TypeError('Name must be a string')
        if name == '':
            raise ValueError('Name cannot be an empty string')
        if name not in self.students:
            raise KeyError('Student not found')
        if not self.students[name]['grades']:
            return None
        return sum(self.students[name]['grades']) / len(self.students[name]['grades'])

    def get_all_students_with_fail_course(self):
        """Get all students who have any score blow 60
        :return: list of str ,student name
        """
        failing_students = []
        for student, courses in self.students.items():
            if any((score < 60 for score in courses.values())):
                failing_students.append(student)
        return list(set(failing_students))

    def get_course_average(self, course):
        if not isinstance(course, str) or not course:
            return None
        if course not in self.students:
            return None
        scores = [score for student in self.students.values() for score in student.get(course, [])]
        if not scores:
            return None
        return sum(scores) / len(scores)

    def get_top_student(self):
        if not self.students:
            raise KeyError('No students in the system')
        top_student = max(self.students, key=lambda name: self.get_gpa(name))
        return top_student

