import unittest

class TestAssessmentSystem(unittest.TestCase):
    def setUp(self):
        self.system = AssessmentSystem()

    def test_add_student_with_valid_data(self):
        self.system.add_student('student 1', 3, 'SE')
        expected = {'student 1': {'name': 'student 1', 'grade': 3, 'major': 'SE', 'courses': {}}}
        self.assertEqual(self.system.students, expected)

    def test_add_student_with_empty_name(self):
        with self.assertRaises(ValueError):
            self.system.add_student('', 3, 'SE')

    def test_add_student_with_negative_grade(self):
        with self.assertRaises(ValueError):
            self.system.add_student('student 1', -1, 'SE')

    def test_add_student_with_grade_greater_than_12(self):
        with self.assertRaises(ValueError):
            self.system.add_student('student 1', 13, 'SE')

    def test_add_student_with_empty_major(self):
        with self.assertRaises(ValueError):
            self.system.add_student('student 1', 3, '')

if __name__ == '__main__':
    unittest.main()
